def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Find the color used for the full-length separator lines.
    line_colors = []
    for row in grid:
        if row[0] != 0 and all(x == row[0] for x in row):
            line_colors.append(row[0])
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if col[0] != 0 and all(x == col[0] for x in col):
            line_colors.append(col[0])
    separator = Counter(line_colors).most_common(1)[0][0]

    sep_rows = {
        r for r, row in enumerate(grid)
        if all(x == separator for x in row)
    }
    sep_cols = {
        c for c in range(w)
        if all(grid[r][c] == separator for r in range(h))
    }

    def runs(size, separators):
        result, current = [], []
        for i in range(size):
            if i in separators:
                if current:
                    result.append(current)
                    current = []
            else:
                current.append(i)
        if current:
            result.append(current)
        return result

    row_tiles = runs(h, sep_rows)
    col_tiles = runs(w, sep_cols)
    if not row_tiles or not col_tiles:
        return [row[:] for row in grid]

    # Each horizontal band's color is the object in its leftmost tile.
    band_colors = []
    for rows in row_tiles:
        counts = Counter(
            grid[r][c]
            for r in rows for c in col_tiles[0]
            if grid[r][c] != 0 and grid[r][c] != separator
        )
        band_colors.append(counts.most_common(1)[0][0] if counts else 0)

    palette = set(band_colors) | {0, separator}
    marker_counts = Counter(
        grid[r][c]
        for rows in row_tiles
        for cols in col_tiles[1:]
        for r in rows for c in cols
        if grid[r][c] not in palette
    )
    if not marker_counts:
        return [row[:] for row in grid]
    marker = marker_counts.most_common(1)[0][0]

    # Record the marker's shape relative to a tile's upper-left corner.
    pattern = set()
    for rows in row_tiles:
        for cols in col_tiles[1:]:
            for r in rows:
                for c in cols:
                    if grid[r][c] == marker:
                        pattern.add((r - rows[0], c - cols[0]))

    out = [row[:] for row in grid]
    for band, rows in enumerate(row_tiles):
        color = band_colors[band]
        for cols in col_tiles:
            for r in rows:
                for c in cols:
                    out[r][c] = 0
            for dr, dc in pattern:
                if dr < len(rows) and dc < len(cols):
                    out[rows[dr]][cols[dc]] = color

    return out
